/**
 * 负责丘比特原槽读取与玩家选择投影。输入为原角色和选择数据；输出为原只读状态引用，
 * 或只含已选择编号的独立玩家视图，其公共类型归 game-contract。
 * 此处不绑定情侣、提交选择库存或判断关系胜负；字段投影不能新增行动许可。
 */
import type { CupidReadState } from "@ai-werewolf-arena/game-contract";
import { playerDataField } from "../player_state";

import type { RoleComponent } from "../../../../core/domain/components/role";
export function getCupidState(role: RoleComponent | undefined): CupidReadState | undefined {
  return (role as { readonly privateState: { readonly cupid?: unknown } } | undefined)?.privateState
    .cupid as CupidReadState | undefined;
}
export function projectCupidState(
  state: CupidReadState,
): import("@ai-werewolf-arena/game-contract/player-state-views").PlayerCupidState {
  const policy = playerDataField(state, "policy"),
    choice = playerDataField(state, "choice"),
    pair = playerDataField(choice, "pairIds");
  // 数组用自己的数据属性读取；共用对象读取器本来拒绝数组，不能因此执行外来编号访问器。
  const pairField = (key: string): unknown => {
    if (!Array.isArray(pair)) return undefined;
    const field = Object.getOwnPropertyDescriptor(pair, key);
    return field && Object.hasOwn(field, "value") ? field.value : undefined;
  };
  const first = pairField("0"),
    second = pairField("1");
  const positive = (id: unknown): id is number =>
    typeof id === "number" && Number.isSafeInteger(id) && id > 0;
  return {
    policy: policy === "lui_meme_lovers_only_v1" ? policy : "netease_2017_cupid_follows_lovers_v1",
    remaining: playerDataField(state, "remaining") === 1 ? 1 : 0,
    choice:
      playerDataField(choice, "day") === 1 &&
      Array.isArray(pair) &&
      pairField("length") === 2 &&
      positive(first) &&
      positive(second) &&
      first !== second
        ? { day: 1, pairIds: [first, second] }
        : null,
  };
}

/**
 * 负责 丘比特 的原资料、初始化与运行贡献装配，内建展示只登记语言中立的具体角色标识。
 * 输入为原板子参数、角色组件与请求上下文；输出为分别登记的资料、运行及展示贡献，工具、阶段、初始化和特权 mock 回调保留原引用与顺序。
 * 展示在实际调用时由角色捕获读取原状态并逐片段交纯展示所有者；本模块不授予租约、执行归档或复制状态。
 * 失败和关闭时仍遵守原机制权限与已付费前缀，不把文案当授权。
 */
import { nativeRolePresentation } from "../presentation-contribution";
import { z } from "zod";
import { RuleError } from "@ai-werewolf-arena/game-contract";
import { text, roleName } from "@ai-werewolf-arena/game-text";
import { CUPID_POLICIES } from "../../../../core/domain/board";
import { Camp, Role, Phase, WinCondition } from "../../../../core/domain/model";
import type { NativeRoleContributions } from "../contracts";
import { isAliveTarget } from "../../validation/contracts";
import { numberOrNull } from "../../llm/helpers";
import { getCupidState, projectCupidState } from "./state";
import { hasCupidNightCommit } from "./relation";
import { CUPID_STAGE } from "./night_stage";
const parameters = z.strictObject({
  policy: z.enum(CUPID_POLICIES).default("netease_2017_cupid_follows_lovers_v1"),
});
export const CUPID_ROLE_PROFILE: NativeRoleContributions = {
  metadata: {
    role: Role.Cupid,
    camp: Camp.Good,
    goodSide: "god",
    maxCount: 1,
    label: roleName("cupid"),
    skillBrief: text("zh-CN", "role.cupid.brief"),
    supportedWinConditions: [WinCondition.SlaughterCity],
    supportedBoardRoles: [
      Role.Cupid,
      Role.Wolf,
      Role.WolfKing,
      Role.WhiteWolfKing,
      Role.Seer,
      Role.Witch,
      Role.Guard,
      Role.Hunter,
      Role.Idiot,
      Role.Villager,
      Role.Knight,
      Role.Dreamer,
      Role.WolfBeauty,
    ],
  },
  runtime: {
    init: (role, ctx) => {
      if (!getCupidState(role))
        role.privateState.cupid = {
          policy: ctx.boardConfig?.cupid?.policy ?? "netease_2017_cupid_follows_lovers_v1",
          remaining: 1,
          choice: null,
        };
    },
    configuration: {
      schema: parameters,
      defaults: { policy: "netease_2017_cupid_follows_lovers_v1" },
      apply: (config, value) => ({ ...config, cupid: parameters.parse(value) }),
      serialize: (config) => parameters.parse(config.cupid ?? {}),
    },
    nightStages: [CUPID_STAGE],
    toolSpecs: [
      {
        name: "choose_lovers",
        parameters: {
          type: "object",
          properties: { first_id: { type: "integer" }, second_id: { type: "integer" } },
          required: ["first_id", "second_id"],
          additionalProperties: false,
        },
        argHint: 'choose_lovers args: {"first_id":number,"second_id":number}',
        userPromptHintKey: "action.choose_lovers.hint",
      },
    ],
    validationRules: {
      choose_lovers: ({ world, role, day, phase, toolCall }) => {
        const state = getCupidState(role);
        if (
          role.role !== Role.Cupid ||
          role.camp !== Camp.Good ||
          !state ||
          state.remaining !== 1 ||
          state.choice !== null ||
          day !== 1 ||
          hasCupidNightCommit(world, day)
        )
          return { code: RuleError.CupidUnavailable };
        if (phase !== Phase.Night) return { code: RuleError.AbilityPhase };
        if (toolCall.name !== "choose_lovers") return { code: RuleError.ToolMismatch };
        const { first_id, second_id } = toolCall.args;
        if (
          !Number.isSafeInteger(first_id) ||
          !Number.isSafeInteger(second_id) ||
          first_id === second_id ||
          !isAliveTarget(world, first_id) ||
          !isAliveTarget(world, second_id)
        )
          return { code: RuleError.CupidTarget };
        return null;
      },
    },
    baselineAction: (_role, request, _other, _camp, _locale, world) => {
      if (!request.allowedTools.includes("choose_lovers") || !world) return null;
      const ids = world.getAliveEntityIds();
      return ids.length < 2
        ? null
        : { name: "choose_lovers", args: { first_id: ids[0]!, second_id: ids[1]! } };
    },
    llmRepair: {
      coerce: {
        choose_lovers: (args) => {
          const first = numberOrNull(args.first_id),
            second = numberOrNull(args.second_id);
          return first === null || second === null ? null : { first_id: first, second_id: second };
        },
      },
    },
  },
  presentation: nativeRolePresentation("cupid"),
};

/**
 * Runs Cupid selection from the current relation candidates. Inputs are the night request and
 * validated paired choice; outputs are the installed lovers relation and its original event. It
 * does not replace the relation owner or independently choose a victory result.
 */
import type { CupidState } from "@ai-werewolf-arena/game-contract";
import { COMPONENT } from "../../../../core/domain/components/names";

import {
  createVictoryComponent,
  type VictoryComponent,
} from "../../../../core/domain/components/victory";
import type { LoversComponent } from "../../../../core/domain/components/lovers";
import { Camp, Phase, Role } from "../../../../core/domain/model";
import { captureNightLife, livingNightLife } from "../../../../core/domain/night_effects";
import type { NightStageHandler } from "../../stages/night/contracts";
import { getCupidState } from "./state";
import { bindLovers, hasCupidNightCommit } from "./relation";

export const CUPID_STAGE: NightStageHandler = {
  id: "cupid",
  priority: 80,
  async execute(ctx) {
    const day = ctx.currentDay();
    if (day !== 1) return;
    if (hasCupidNightCommit(ctx.world, day)) throw new Error("cupid_night_reentry_after_commit");
    for (const actorId of ctx.getAliveByRole(Role.Cupid)) {
      const role = ctx.world.getComponent(actorId, COMPONENT.Role)!,
        state = getCupidState(role),
        life = captureNightLife(ctx.world, actorId),
        victory = ctx.world.getComponent(actorId, COMPONENT.Victory);
      if (!state || !life || !victory || role.camp !== Camp.Good) continue;
      const privateState = role.privateState,
        policy = state.policy,
        affiliations = victory.affiliations,
        membership = JSON.stringify(affiliations);
      const current = () =>
        ctx.isCurrent() &&
        ctx.currentDay() === day &&
        ctx.world.getComponent(actorId, COMPONENT.Role) === role &&
        role.role === Role.Cupid &&
        role.camp === Camp.Good &&
        role.privateState === privateState &&
        getCupidState(role) === state &&
        state.policy === policy &&
        state.remaining === 1 &&
        state.choice === null &&
        livingNightLife(ctx.world, life) &&
        ctx.world.getComponent(actorId, COMPONENT.Victory) === victory &&
        victory.affiliations === affiliations &&
        JSON.stringify(affiliations) === membership &&
        !hasCupidNightCommit(ctx.world, day);
      if (!current()) continue;
      let completed = false;
      for (let attempt = 0; attempt < 3; attempt++) {
        if (!current()) break;
        const targets = new Map(
          ctx.world.getAliveEntityIds().map((id) => {
            const targetRole = ctx.world.getComponent(id, COMPONENT.Role)!,
              targetVictory = ctx.world.getComponent(id, COMPONENT.Victory)!;
            return [
              id,
              {
                life: captureNightLife(ctx.world, id)!,
                role: targetRole,
                kind: targetRole.role,
                camp: targetRole.camp,
                privateState: targetRole.privateState,
                victory: targetVictory,
                affiliations: targetVictory.affiliations,
                membership: JSON.stringify(targetVictory.affiliations),
              },
            ] as const;
          }),
        );
        if (targets.size < 2) throw new Error("cupid_valid_action_missing");
        const request = ctx.makeRequest(actorId, ["choose_lovers"], {
          stage: "cupid",
          requiresAction: true,
          allow_fallback: false,
          action_failure_policy: "error",
          ...(attempt ? { retry_attempt: attempt, retry_max: 2 } : {}),
        });
        if (!current()) break;
        const action = await ctx.actionProvider.getAction(request);
        if (!current()) break;
        if (action?.name !== "choose_lovers") continue;
        const valid = ctx.toolGateway.validateAndSanitize(ctx.world, actorId, action, {
          phase: Phase.Night,
          day,
        });
        if (!current() || !valid.ok || valid.sanitizedCall?.name !== "choose_lovers") continue;
        const pairIds: [number, number] = [
          valid.sanitizedCall.args.first_id,
          valid.sanitizedCall.args.second_id,
        ];
        const selected = pairIds.map((id) => targets.get(id));
        if (
          selected.some(
            (target, index) =>
              !target ||
              !livingNightLife(ctx.world, target.life) ||
              ctx.world.getComponent(pairIds[index]!, COMPONENT.Role) !== target.role ||
              target.role.role !== target.kind ||
              target.role.camp !== target.camp ||
              target.role.privateState !== target.privateState ||
              (target.camp !== Camp.Good && target.camp !== Camp.Wolf) ||
              ctx.world.getComponent(pairIds[index]!, COMPONENT.Victory) !== target.victory ||
              target.victory.affiliations !== target.affiliations ||
              JSON.stringify(target.affiliations) !== target.membership,
          )
        )
          continue;
        const first = selected[0]!,
          second = selected[1]!,
          mixed = first.camp !== second.camp;
        const record: LoversComponent = Object.freeze({
          actorId,
          day: 1,
          policy,
          pairIds: Object.freeze(pairIds),
          pairCamps: Object.freeze([first.camp, second.camp]) as LoversComponent["pairCamps"],
          groupId: "cupid_lovers",
          mixed,
        });
        const memberIds = new Set(pairIds);
        if (policy === "netease_2017_cupid_follows_lovers_v1") memberIds.add(actorId);
        // Final authorization has no await before atomic relation/state/membership writes.
        bindLovers(ctx.world, record, [first.life, second.life]);
        (state as Pick<CupidState, "remaining">).remaining = 0;
        (state as Pick<CupidState, "choice">).choice = { day: 1, pairIds: [...pairIds] };
        for (const id of memberIds)
          ctx.world.addComponent(
            id,
            COMPONENT.Victory,
            createVictoryComponent([
              mixed
                ? { kind: "relationship", groupId: record.groupId }
                : { kind: "faction", faction: first.camp },
            ]),
          );
        ctx.events.push({
          timestamp: Date.now(),
          type: "cupid_lovers_chosen",
          payload: { actorId, day: 1, pairIds: [...pairIds] },
        });
        for (const id of pairIds)
          ctx.events.push({
            timestamp: Date.now(),
            type: "lover_recognized",
            payload: { actorId: id, partnerId: pairIds.find((target) => target !== id)! },
          });
        ctx.events.push({
          timestamp: Date.now(),
          type: "cupid_relation_resolved",
          payload: record,
        });
        completed = true;
        break;
      }
      if (!completed && current()) throw new Error("cupid_valid_action_missing");
    }
  },
};

/**
 * 提供丘比特的原生状态与玩家知识出口。getter 保留原槽引用，玩家投影保留已有恋人
 * 选择的可见字段；展示不能据此获知恋人秘密阵营。恋人关系、殉情与胜利归属仍由具体
 * 机制决定，本出口不创建第二状态、补交选择、授权请求或渲染文案。
 * 输入为原角色对象；查询在展示时点读取，不拥有关系写权，失败不在出口兜底或补交。
 */

export { getCupidState } from "./state";

export { projectCupidState } from "./state";

/**
 * 负责混血儿初态、原槽读取、榜样选择资格和玩家投影。输入为原角色、选择数据与日次；
 * 输出为原只读存储引用或单独复制的选择，公开 DTO 类型归公共契约。
 * 本模块不写榜样选择、改变隐藏胜利归属或授予行动许可；真正选择提交由夜间机制负责。
 */
import type { HybridState, HybridReadState } from "@ai-werewolf-arena/game-contract";
import type { PlayerHybridState } from "@ai-werewolf-arena/game-contract/player-state-views";
import type { RoleComponent } from "../../../../core/domain/components/role";
export const freshHybridState = (): HybridState => ({ remaining: 1, choice: null });
export function getHybridState(role: RoleComponent | undefined): HybridReadState | undefined {
  return (role as { readonly privateState: { readonly hybrid?: unknown } } | undefined)
    ?.privateState.hybrid as HybridReadState | undefined;
}
export function projectHybridState(state: HybridReadState): PlayerHybridState {
  return {
    remaining: state.remaining,
    choice: state.choice ? { day: state.choice.day, targetId: state.choice.targetId } : null,
  };
}
export function canChooseExemplar(state: HybridReadState, day: number): boolean {
  return day === 1 && state.remaining === 1 && state.choice === null;
}

/**
 * 负责 混血儿 的原资料、初始化与运行贡献装配，内建展示只登记语言中立的具体角色标识。
 * 输入为原板子参数、角色组件与请求上下文；输出为分别登记的资料、运行及展示贡献，工具、阶段、初始化和特权 mock 回调保留原引用与顺序。
 * 展示在实际调用时由角色捕获读取原状态并逐片段交纯展示所有者；本模块不授予租约、执行归档或复制状态。
 * 失败和关闭时仍遵守原机制权限与已付费前缀，不把文案当授权。
 */
import { nativeRolePresentation } from "../presentation-contribution";
import { z } from "zod";
import { RuleError } from "@ai-werewolf-arena/game-contract";
import { text, roleName } from "@ai-werewolf-arena/game-text";
import { COMPONENT } from "../../../../core/domain/components/names";
import type { VictoryComponent } from "../../../../core/domain/components/victory";
import { Camp, Role, Phase } from "../../../../core/domain/model";
import type { NativeRoleContributions } from "../contracts";
import { isAliveTarget } from "../../validation/contracts";
import { numberOrNull } from "../../llm/helpers";
import { canChooseExemplar, freshHybridState, getHybridState, projectHybridState } from "./state";
import { HYBRID_STAGE } from "./night_stage";

export const HYBRID_ROLE_PROFILE: NativeRoleContributions = {
  metadata: {
    role: Role.Hybrid,
    camp: Camp.Good,
    goodSide: "villager",
    maxCount: 1,
    label: roleName("hybrid"),
    skillBrief: text("zh-CN", "role.hybrid.brief"),
    supportedBoardRoles: [
      Role.Hybrid,
      Role.Wolf,
      Role.WolfKing,
      Role.HiddenWolf,
      Role.Seer,
      Role.Witch,
      Role.Guard,
      Role.Hunter,
      Role.Idiot,
      Role.Villager,
    ],
  },
  runtime: {
    initialVictoryAffiliations: [],
    init: (role) => {
      if (!getHybridState(role)) role.privateState.hybrid = freshHybridState();
    },
    configuration: {
      schema: z.strictObject({}),
      defaults: {},
      apply: (config) => config,
      serialize: () => ({}),
    },
    nightStages: [HYBRID_STAGE],
    toolSpecs: [
      {
        name: "choose_exemplar",
        parameters: {
          type: "object",
          properties: { target_id: { type: "integer" } },
          required: ["target_id"],
          additionalProperties: false,
        },
        argHint: 'choose_exemplar args: {"target_id":number}',
        userPromptHintKey: "action.choose_exemplar.hint",
      },
    ],
    validationRules: {
      choose_exemplar: ({ world, actorId, role, day, phase, toolCall }) => {
        const state = getHybridState(role),
          victory = world.getComponent(actorId, COMPONENT.Victory);
        if (
          role.role !== Role.Hybrid ||
          role.camp !== Camp.Good ||
          !state ||
          day === undefined ||
          !canChooseExemplar(state, day) ||
          !victory ||
          victory.affiliations.length !== 0
        )
          return { code: RuleError.HybridUnavailable };
        if (phase !== Phase.Night) return { code: RuleError.AbilityPhase };
        if (toolCall.name !== "choose_exemplar") return { code: RuleError.ToolMismatch };
        if (toolCall.args.target_id === actorId || !isAliveTarget(world, toolCall.args.target_id))
          return { code: RuleError.HybridTarget };
        return null;
      },
    },
    llmRepair: {
      coerce: {
        choose_exemplar: (args) => {
          const target = numberOrNull(args.target_id);
          return target === null ? null : { target_id: target };
        },
      },
    },
  },
  presentation: nativeRolePresentation("hybrid"),
};

/**
 * Executes Hybrid exemplar selection and records its actual night commitment. Inputs are the
 * current Hybrid body, candidates and validated tool; outputs are the chosen exemplar state and
 * corresponding facts. Selection never replaces the original role component or silently repeats
 * a completed choice.
 */
import type { HybridState } from "@ai-werewolf-arena/game-contract";
import { COMPONENT } from "../../../../core/domain/components/names";

import {
  createVictoryComponent,
  type VictoryComponent,
} from "../../../../core/domain/components/victory";
import { Camp, Phase, Role } from "../../../../core/domain/model";
import { captureNightLife, livingNightLife } from "../../../../core/domain/night_effects";
import type { World } from "../../../../core/domain/world";
import type { NightStageHandler } from "../../stages/night/contracts";
import { canChooseExemplar, getHybridState } from "./state";

const committed = new WeakMap<World, Set<number>>();
export function hasHybridNightCommit(world: World, day: number): boolean {
  return committed.get(world)?.has(day) ?? false;
}

export const HYBRID_STAGE: NightStageHandler = {
  id: "hybrid",
  priority: 110,
  async execute(ctx) {
    const day = ctx.currentDay();
    if (day !== 1) return;
    for (const actorId of ctx.getAliveByRole(Role.Hybrid)) {
      const role = ctx.world.getComponent(actorId, COMPONENT.Role)!;
      const state = getHybridState(role),
        life = captureNightLife(ctx.world, actorId);
      const victory = ctx.world.getComponent(actorId, COMPONENT.Victory);
      if (!state || !life || !victory || role.camp !== Camp.Good) continue;
      const privateState = role.privateState,
        affiliations = victory.affiliations;
      const current = () =>
        ctx.isCurrent() &&
        ctx.currentDay() === day &&
        ctx.world.getComponent(actorId, COMPONENT.Role) === role &&
        role.role === Role.Hybrid &&
        role.camp === Camp.Good &&
        role.privateState === privateState &&
        getHybridState(role) === state &&
        livingNightLife(ctx.world, life) &&
        ctx.world.getComponent(actorId, COMPONENT.Victory) === victory &&
        victory.affiliations === affiliations &&
        affiliations.length === 0 &&
        canChooseExemplar(state, day);
      if (!current()) continue;
      let completed = false;
      for (let attempt = 0; attempt < 3; attempt++) {
        if (!current()) break;
        const targets = new Map(
          ctx.world
            .getAliveEntityIds()
            .filter((id) => id !== actorId)
            .map((id) => {
              const targetRole = ctx.world.getComponent(id, COMPONENT.Role)!;
              return [
                id,
                {
                  life: captureNightLife(ctx.world, id)!,
                  role: targetRole,
                  kind: targetRole.role,
                  camp: targetRole.camp,
                  privateState: targetRole.privateState,
                },
              ] as const;
            }),
        );
        if (!targets.size) throw new Error("hybrid_valid_action_missing");
        const action = await ctx.actionProvider.getAction(
          ctx.makeRequest(actorId, ["choose_exemplar"], {
            stage: "hybrid",
            requiresAction: true,
            allow_fallback: false,
            ...(attempt ? { retry_attempt: attempt, retry_max: 2 } : {}),
          }),
        );
        if (!current()) break;
        if (action?.name !== "choose_exemplar") continue;
        const valid = ctx.toolGateway.validateAndSanitize(ctx.world, actorId, action, {
          phase: Phase.Night,
          day,
        });
        if (!current() || !valid.ok || valid.sanitizedCall?.name !== "choose_exemplar") continue;
        const targetId = valid.sanitizedCall.args.target_id,
          target = targets.get(targetId);
        if (
          !target ||
          !livingNightLife(ctx.world, target.life) ||
          ctx.world.getComponent(targetId, COMPONENT.Role) !== target.role ||
          target.role.role !== target.kind ||
          target.role.camp !== target.camp ||
          target.role.privateState !== target.privateState ||
          (target.camp !== Camp.Good && target.camp !== Camp.Wolf)
        )
          continue;
        const membership = createVictoryComponent([{ kind: "faction", faction: target.camp }]);
        // No await between the final checks and both owned writes. A second reply loses its original scope.
        (state as Pick<HybridState, "remaining">).remaining = 0;
        (state as Pick<HybridState, "choice">).choice = { day, targetId };
        ctx.world.addComponent(actorId, COMPONENT.Victory, membership);
        const days = committed.get(ctx.world) ?? new Set<number>();
        days.add(day);
        committed.set(ctx.world, days);
        ctx.events.push({
          timestamp: Date.now(),
          type: "hybrid_exemplar_chosen",
          payload: { actorId, day, targetId },
        });
        ctx.events.push({
          timestamp: Date.now(),
          type: "hybrid_affiliation_resolved",
          payload: { actorId, day, targetId, faction: target.camp },
        });
        completed = true;
        break;
      }
      if (!completed && current()) throw new Error("hybrid_valid_action_missing");
    }
  },
};

/**
 * 提供混血儿的原生选择状态与可见玩家知识出口。getter 保留原状态引用，投影保留
